function filter(){const query=document.querySelector('#search').value.toLowerCase().trim();let count=0;products.forEach(p=>{const visible=(category==='All'||p.category===category)&&(shark==='All'||p.sharks.includes(shark))&&[p.name,p.description,p.shark,p.category].join(' ').toLowerCase().includes(query);document.querySelector(`[data-id="${p.id}"]`).classList.toggle('hidden',!visible);if(visible)count++});document.querySelector('#count').textContent=String(count).padStart(2,'0')+' FINDS';document.querySelector('#count').setAttribute('aria-live','polite');document.querySelector('#empty').hidden=count!==0}
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});filter()}));document.querySelectorAll('[data-shark]').forEach(b=>b.addEventListener('click',()=>{shark=b.dataset.shark;document.querySelectorAll('[data-shark]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});filter()}));document.querySelector('#search').addEventListener('input',filter);document.querySelector('#reset').addEventListener('click',()=>{document.querySelector('#search').value='';document.querySelector('[data-category="All"]').click();document.querySelector('[data-shark="All"]').click()});document.querySelectorAll('[data-category],[data-shark]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));['#close-dialog','#back-to-finds'].forEach(s=>document.querySelector(s).addEventListener('click',()=>document.querySelector('#link-dialog').close()));document.querySelector('#link-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('reveal');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.card').forEach(c=>observer.observe(c));let ticking=false;function update(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max>0?scrollY/max*100:0)+'%';ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(update);ticking=true}},{passive:true});update();

const ticker=document.querySelector('.ticker');
const tickerToggle=document.querySelector('.ticker-toggle');
if(ticker && tickerToggle){tickerToggle.addEventListener('click',()=>{const paused=ticker.classList.toggle('paused');tickerToggle.setAttribute('aria-pressed',String(paused));tickerToggle.setAttribute('aria-label',paused?'Resume Shark quotes':'Pause Shark quotes');tickerToggle.title=paused?'Resume quotes':'Pause quotes';tickerToggle.innerHTML='<span aria-hidden="true">'+(paused?'▶':'Ⅱ')+'</span>';});}

const reduceSparkleMotion=typeof matchMedia==='function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
function sparkleBurst(card,x,y){
 if(reduceSparkleMotion)return;
 const burst=document.createElement('span');burst.className='sparkle-burst';burst.setAttribute('aria-hidden','true');burst.style.setProperty('--burst-x',x+'px');burst.style.setProperty('--burst-y',y+'px');
 const colors=['#fff8c2','#e9ff68','#ffb6d9','#ffffff','#c7c5ff'];
 for(let i=0;i<6;i++){const glint=document.createElementNS('http://www.w3.org/2000/svg','svg');glint.setAttribute('viewBox','0 0 32 32');glint.classList.add('burst-glint');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M16 0C17.5 12 20 14.5 32 16C20 17.5 17.5 20 16 32C14.5 20 12 17.5 0 16C12 14.5 14.5 12 16 0Z');glint.append(path);const angle=(i/6)*Math.PI*2;const distance=25+(i%3)*12;glint.style.setProperty('--dx',Math.cos(angle)*distance+'px');glint.style.setProperty('--dy',Math.sin(angle)*distance+'px');glint.style.setProperty('--size',(9+(i%3)*5)+'px');glint.style.setProperty('--glint-color',colors[i%colors.length]);burst.append(glint)}
 card.append(burst);setTimeout(()=>burst.remove(),900);
}
document.querySelectorAll('.card').forEach(card=>{let lastBurst=0;card.addEventListener('pointerenter',e=>{if(e.pointerType==='touch')return;const now=Date.now();if(now-lastBurst<1300)return;lastBurst=now;const visual=card.querySelector('.product-visual');sparkleBurst(card,visual.offsetLeft+visual.offsetWidth-24,visual.offsetTop+26)});card.querySelectorAll('a').forEach(link=>link.addEventListener('pointerdown',e=>{const box=card.getBoundingClientRect();sparkleBurst(card,e.clientX-box.left,e.clientY-box.top)}));});

// Trigger once on approach, then rearm after the pointer leaves the button area.
if(typeof matchMedia==='function' && matchMedia('(hover: hover) and (pointer: fine)').matches){
 const shopButtons=Array.from(document.querySelectorAll('.card a.shop'));
 const bounceState=new WeakMap();let bounceFrame=0,nearbyPointer=null;
 function checkNearbyButtons(){
  bounceFrame=0;if(!nearbyPointer || matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const {x,y}=nearbyPointer;
  shopButtons.forEach(button=>{
   const box=button.getBoundingClientRect();if(box.width===0 || box.height===0)return;
   const dx=Math.max(box.left-x,0,x-box.right),dy=Math.max(box.top-y,0,y-box.bottom);
   const distance=Math.hypot(dx,dy);let state=bounceState.get(button);
   if(!state){state={armed:true,last:0};bounceState.set(button,state)}
   if(distance>105)state.armed=true;
   if(distance<=65 && state.armed && Date.now()-state.last>1100){
    state.armed=false;state.last=Date.now();button.classList.remove('nearby-bounce');
    void button.offsetWidth;button.classList.add('nearby-bounce');
   }
  });
 }
 function scheduleNearbyCheck(){if(!bounceFrame)bounceFrame=requestAnimationFrame(checkNearbyButtons)}
 document.addEventListener('pointermove',event=>{if(event.pointerType!=='mouse')return;nearbyPointer={x:event.clientX,y:event.clientY};scheduleNearbyCheck()},{passive:true});
 addEventListener('scroll',scheduleNearbyCheck,{passive:true});
 document.addEventListener('pointerleave',()=>{nearbyPointer=null;shopButtons.forEach(button=>{const state=bounceState.get(button);if(state)state.armed=true})});
 shopButtons.forEach(button=>button.addEventListener('animationend',event=>{if(event.animationName==='nearby-bounce')button.classList.remove('nearby-bounce')}));
}
